CREATE EXTENSION IF NOT EXISTS pgcrypto;
WITH owners AS ( SELECT DISTINCT u.id AS user_id, u.email, u.api_key FROM users u JOIN company_projects cp ON cp.user_id = u.id ), new_companies AS ( INSERT INTO companies (name, api_key_hash, api_key_last_rotated_at, active, created_at, updated_at, version) SELECT o.email, encode(digest(COALESCE(o.api_key, encode(gen_random_bytes(32), 'hex')), 'sha256'), 'base64'), now(), true, now(), now(), 0 FROM owners o RETURNING id, name ) INSERT INTO company_memberships (user_id, company_id, company_role, created_at, updated_at, version) SELECT o.user_id, nc.id, 'OWNER', now(), now(), 0 FROM owners o JOIN new_companies nc ON nc.name = o.email;
UPDATE company_projects cp SET company_id = cm.company_id, created_by_user_id = cp.user_id, updated_by_user_id = cp.user_id FROM company_memberships cm WHERE cm.user_id = cp.user_id;
